CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), customer_id uuid NOT NULL, invoice_number text NOT NULL, invoice_date date NOT NULL, due_date date NOT NULL, subtotal numeric(18,2) NOT NULL DEFAULT 0, tax numeric(18,2) NOT NULL DEFAULT 0, discount numeric(18,2) NOT NULL DEFAULT 0, total numeric(18,2) NOT NULL CHECK(total>=0), paid_amount numeric(18,2) NOT NULL DEFAULT 0, outstanding_amount numeric(18,2) GENERATED ALWAYS AS (total-paid_amount) STORED, status text NOT NULL CHECK(status IN ('DRAFT','PENDING','PARTIAL','PAID','OVERDUE','CANCELLED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (organization_id,customer_id) REFERENCES customers(organization_id,id), UNIQUE(organization_id,invoice_number), UNIQUE(organization_id,id)); CREATE INDEX invoices_org_due_idx ON invoices(organization_id,due_date); CREATE INDEX invoices_org_status_idx ON invoices(organization_id,status);
